<script>
  import Icon from "./Icon.svelte";
  let { inventory, projects, busy } = $props();
</script>

<div class="title-row"><h1>Credentials</h1><span class="muted">{inventory.filteredCredentials.length} of {inventory.credentials.length}</span></div>
<div class="filters" aria-label="Credential filters">{#each [["all", "All"], ["recent", "Recent"], ["project", "By project"]] as [value, label]}<button class:active={inventory.filter === value} aria-pressed={inventory.filter === value} onclick={() => { inventory.filter = value; void inventory.loadCredentials(); }}>{label}</button>{/each}</div>
<div class="field-row">{#if inventory.filter === "project"}<div><label for="list-project">Project</label><select id="list-project" bind:value={inventory.project} onchange={inventory.loadCredentials}>{#each projects as item}<option value={item.name}>{item.name}</option>{/each}</select></div>{/if}<div><label for="search-credentials">Search</label><input id="search-credentials" type="search" bind:value={inventory.search} /></div></div>
{#if !inventory.credentials.length}<p class="muted">No credentials in this project.</p>{:else}
  <ul class="credential-list">{#each inventory.filteredCredentials as credential (`${credential.project || inventory.project}:${credential.id || credential.name}`)}<li><div class="credential-row"><div class="grow"><strong>{credential.name}</strong><span class="muted">{credential.project || inventory.project} · {credential.partition || credential.type}</span></div><button class="icon-button" aria-label={`Copy token for ${credential.name}`} disabled={busy} onclick={() => inventory.credentialAction("copy_token", credential)}><Icon name="copy" size={14} /></button><button class="icon-button" aria-label={`Rotate token for ${credential.name}`} disabled={busy} onclick={() => { inventory.rotateTarget = credential; inventory.removeTarget = null; }}><Icon name="refresh" size={14} /></button><button class="icon-button danger" aria-label={`Remove ${credential.name}`} disabled={busy} onclick={() => { inventory.removeTarget = credential; inventory.rotateTarget = null; }}><Icon name="trash" size={14} /></button></div>{#if inventory.rotateTarget === credential}<div class="delete-review"><span>Rotate the token for {credential.name} in {credential.project || inventory.project}? The current token will stop working.</span><div class="actions"><button onclick={() => (inventory.rotateTarget = null)}>Cancel</button><button class="primary" disabled={busy} onclick={() => inventory.credentialAction("rotate_credential", credential)}>Rotate token</button></div></div>{/if}{#if inventory.removeTarget === credential}<div class="delete-review"><span>Remove {credential.name} from {credential.project || inventory.project}?</span><div class="actions"><button onclick={() => (inventory.removeTarget = null)}>Cancel</button><button class="danger-button" disabled={busy} onclick={() => inventory.credentialAction("remove_credential", credential)}>Remove credential</button></div></div>{/if}</li>{/each}</ul>
{/if}
